import openpyxl
from openpyxl.styles import Font, Fill, Border, Alignment, Protection
orig = openpyxl.load_workbook('/mnt/hhq/data/data_pipeline/generated_tasks/route_b_s2_only/template/seed_collection_0082_template_6576_input.xlsx')
new = openpyxl.load_workbook('seed_collection_0082_template_6576_input.xlsx')
# Compare styles for all cells (non-values attributes) 
mismatch=[]
for name in orig.sheetnames:
    ow=orig[name]; nw=new[name]
    for row in ow.iter_rows():
        for c in row:
            o=c; n=nw[c.coordinate]
            # compare number format, font, fill, border, alignment, protection
            attrs = ['number_format']
            for attr in attrs:
                if getattr(o, attr) != getattr(n, attr):
                    mismatch.append((name,c.coordinate,attr,getattr(o,attr),getattr(n,attr)))
            # compare style objects with repr-ish
            for attr in ['font','fill','border','alignment','protection']:
                so=getattr(o,attr); sn=getattr(n,attr)
                # compare key attributes
                def desc(s):
                    if attr=='font':
                        return (s.name,s.size,s.bold,s.italic,s.underline,s.strikethrough,s.color.rgb if s.color else None)
                    if attr=='fill':
                        return (s.fill_type, s.fgColor.rgb if s.fgColor else None, s.bgColor.rgb if s.bgColor else None)
                    if attr=='border':
                        return tuple((side, getattr(s, side).style, getattr(s, side).color.rgb if getattr(s, side).color else None) for side in ['left','right','top','bottom'])
                    if attr=='alignment':
                        return (s.horizontal,s.vertical,s.wrap_text,s.shrink_to_fit,s.indent)
                    if attr=='protection':
                        return (s.locked,s.hidden)
                    return str(s)
                if desc(so) != desc(sn):
                    mismatch.append((name,c.coordinate,attr,desc(so),desc(sn)))
print('style mismatches', len(mismatch))
for m in mismatch[:20]:
    print(m)
